def is_good_triple(x, y, z):
    # Check if (x+1)^y / (x^z + 1) is an integer
    numerator = (x + 1)**y
    denominator = x**z + 1

    if denominator == 0:
        # Should not happen since x >= 1, z >= 1
        return False

    return numerator % denominator == 0

good_triples = []
limit = 10

for x in range(1, limit + 1):
    for y in range(1, limit + 1):
        for z in range(1, limit + 1):
            if is_good_triple(x, y, z):
                good_triples.append((x, y, z))

print(f"Found {len(good_triples)} good triples up to 10:")
for triple in good_triples:
    print(triple)

